<template><view class="page"><AppHeader/><view class="content result-head"><text class="eyebrow">{{module.en}} CREATES A MORE YOU</text><view class="section-title">{{isTryon?'你的试衣效果':`你的${module.name}形象提案`}}</view><view class="lead">{{isTryon?'AI 生成效果仅供视觉参考，不代表实际尺码与合身度':'基于你的真实特征与生活方式'}}</view></view><view class="content result-grid"><view class="comparison"><view class="result-banner">{{isTryon?'人物原图 · 服装参考 · 试穿结果':'柔和轮廓 · 轻盈层次 · 低维护'}}</view><view class="before-after" :class="{tryon:isTryon}"><view><text>人物原图</text><image :src="item?.photo_url||'/static/design/portrait-original.webp'" mode="aspectFill"/></view><template v-if="isTryon"><b>＋</b><view><text>服装参考</text><image :src="item?.garment_url" mode="aspectFit"/></view><b>→</b></template><template v-else><b>→</b></template><view><text>{{isTryon?'试穿结果':'建议效果'}}</text><image :src="item?.result_image_url||'/static/design/portrait-result.webp'" mode="aspectFill"/></view></view></view><view class="recommend"><view class="section-title">{{isTryon?'本次试穿说明':'最适合你的方向'}}</view><view v-if="!isTryon" class="options"><view v-for="(x,i) in options" :key="x"><image class="image-monochrome" :src="`/static/design/result-option-${i+1}.webp`" mode="aspectFill"/><text>{{x}}</text></view></view><view class="analysis-copy">{{item?.analysis||'生成结果用于视觉参考，请以真实试穿和商品尺码为准。'}}</view><view class="actions"><view class="editorial-btn" @click="again">{{isTryon?'再试一件':'重新咨询'}}</view></view></view></view></view></template>
<script setup lang="ts">import{ref,onMounted,computed}from'vue';import{getConsultation,type Consultation}from'../../api';import{draft,modules}from'../../state';const item=ref<Consultation>();const module=computed(()=>modules[(item.value?.module||draft.module) as keyof typeof modules]);const isTryon=computed(()=>item.value?.module==='tryon');const options=['自然层次中长发','气质法式短发','温柔低扎发'];onMounted(async()=>{const p=getCurrentPages().at(-1)as{options?:Record<string,string>}|undefined;const id=String(p?.options?.id||'');if(id)item.value=await getConsultation(id)});function again(){isTryon.value?uni.switchTab({url:'/pages/tryon/index'}):uni.navigateTo({url:'/pages/modules/index'})}</script>
<style scoped>.result-head{margin-top:45px}.result-grid{display:grid;gap:45px;margin-top:20px}.result-banner{background:linear-gradient(100deg,#fff,#d8dbe0,#fff);padding:20px;font-family:"Songti SC",serif;font-size:24px;margin-bottom:18px}.before-after{display:grid;grid-template-columns:1fr 30px 1fr;align-items:center;gap:12px}.before-after.tryon{grid-template-columns:1fr 24px 1fr 24px 1fr}.before-after view{position:relative}.before-after text{position:absolute;z-index:1;left:18px;top:15px;font-family:"Songti SC",serif;background:rgba(255,255,255,.75);padding:4px 7px}.before-after image{width:100%;height:460px}.before-after b{text-align:center;font-size:26px;font-weight:300}.options{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.options image{width:100%;height:190px}.options text{display:block;font-family:"Songti SC",serif;font-size:16px;margin-top:10px}.analysis-copy{white-space:pre-wrap;line-height:1.9;margin-top:25px;padding:25px;background:rgba(255,255,255,.72);border-top:1px solid var(--line)}@media(max-width:700px){.before-after.tryon{grid-template-columns:1fr}.before-after.tryon b{transform:rotate(90deg)}}@media(min-width:900px){.result-grid{grid-template-columns:1.35fr .8fr}.result-head .section-title{font-size:46px}.options image{height:220px}}</style>
